var kQn = "enable__mcp__claude-in-chrome", EQn = "enable__mcp__remote-devices__Claude_Browser", vQn = "enable__mcp__remote-devices__computer", dzo = "request_computer", TAa = "Enable Claude in Chrome, the Claude extension in the Chrome browser on the user's own computer, for this conversation. If you already have tools whose names contain claude-in-chrome__ or Claude_in_Chrome__, use those directly instead of calling this. Otherwise call it once, before any other Claude in Chrome tool, when the user asks you to do something in their browser or on a website that needs their own sign-in, or explicitly asks for Claude in Chrome. Do not call it for questions you can answer from the conversation or with web search, or merely because a request mentions a website.", CAa = "Enable Claude in Chrome, the Claude extension in the Chrome browser on the user's own computer, for this conversation. If you already have tools whose names contain claude-in-chrome__ or Claude_in_Chrome__, use those directly instead of calling this. Otherwise call it once, before any other Claude in Chrome tool, when the user asks you to do something in their browser or on a website that needs their own sign-in, when a step in a skill or task the user asked you to carry out needs their browser or such a website, or when the user explicitly asks for Claude in Chrome. If the tools it turns on, or the tools for files on that computer, are missing from your tool list, calling it is how they are added, possibly a turn later. Do not call it for questions you can answer from the conversation or with web search, or merely because a request mentions a website.", AAa = "Enable the browser built into the Claude desktop app on the user's computer for this conversation. If you already have tools whose names contain Claude_Browser__, use those directly instead of calling this. Otherwise call it once, before any other Claude app browser tool, when the user asks you to do something in the Claude app's own browser or on a website that needs their own sign-in, or explicitly asks for that browser. Do not call it for questions you can answer from the conversation or with web search, or merely because a request mentions a website.", RAa = "Enable the browser built into the Claude desktop app on the user's computer for this conversation. If you already have tools whose names contain Claude_Browser__, use those directly instead of calling this. Otherwise call it once, before any other Claude app browser tool, when the user asks you to do something in the Claude app's own browser or on a website that needs their own sign-in, when a step in a skill or task the user asked you to carry out needs that browser or such a website, or when the user explicitly asks for that browser. If the tools it turns on, or the tools for files on that computer, are missing from your tool list, calling it is how they are added, possibly a turn later. Do not call it for questions you can answer from the conversation or with web search, or merely because a request mentions a website.", O4s = { type: "object", properties: { task: { type: "string", description: "Optional: what you are about to do in the browser, in one or two sentences." } }, additionalProperties: false }, t = `Any of them that was announced as available through ${import_chunk_t99xdws4.co} must be loaded before you call it, unless ${import_chunk_t99xdws4.co} has loaded it since`, o = `${t}: load the ones you expect to need in one ${import_chunk_t99xdws4.co} call (for example, query "select:<name>[,<name>...]"), and use them once that result has come back, not in the same reply`, n = "If no tool with such a name is in your list or was announced, or you have since been told that they are no longer available, do not call or load one. That applies to those tools only.", xAa = `Claude in Chrome needs no enabling: its tools are the ones whose names contain claude-in-chrome or Claude_in_Chrome. ${o}. ${n} If you have no browser tool of any kind, tell the user in one plain sentence that you can't use Claude in Chrome in this chat right now, and continue with what you can do here. You don't know the cause: don't say that Chrome or its extension isn't connected, and suggest no steps or settings for Claude in Chrome.`, PAa = `The Claude desktop app's built-in browser needs no enabling: its tools are the ones whose names contain Claude_Browser. ${o}. ${n} If you have no browser tool of any kind, tell the user that the browser in their Claude desktop app is not available in this chat right now and continue with what you can do here.`, OAa = "Enable computer use on the user's own computer for this conversation, so you can see its screen and work in its applications (take screenshots, click, type, scroll, open apps). If you already have tools whose names start with mcp__remote-devices__computer_, use those directly instead of calling this. Otherwise call it once, before any other computer-use tool, when the user asks you to do something in an application on their computer, or explicitly asks you to use their computer or their screen. Do not call it for questions you can answer from the conversation or with web search, for work that only needs their web browser, or merely because a request mentions an application.", IAa = "Enable computer use on the user's own computer for this conversation, so you can see its screen and work in its applications (take screenshots, click, type, scroll, open apps). If you already have tools whose names start with mcp__remote-devices__computer_, use those directly instead of calling this. Otherwise call it once, before any other computer-use tool, when the user asks you to do something in an application on their computer, when a step in a skill or task the user asked you to carry out needs an application on their computer, or when the user explicitly asks you to use their computer or their screen. If the tools it turns on, or the tools for files on that computer, are missing from your tool list, calling it is how they are added, possibly a turn later. Do not call it for questions you can answer from the conversation or with web search, for work that only needs their web browser, or merely because a request mentions an application.", MAa = { type: "object", properties: { task: { type: "string", description: "Optional: what you are about to do on the computer, in one or two sentences." } }, additionalProperties: false }, e = `mcp__${import_chunk_qdcbcsg7.$n}__computer_`, HAa = `The computer-use tools are the ${e} tools; there is no separate enable step. ${t}: load them all in one ${import_chunk_t99xdws4.co} call (query "${e}", max_results 100), and use them once that result has come back, not in the same reply. Try the user's request with them, asking for access to the applications you need first, the way those tools describe. Don't tell the user their computer is connected until a call to one of them has succeeded; if calls keep not responding, the Claude app on the user's computer isn't answering: it may be closed or the computer asleep. Tell the user that, ask them to open the Claude app on that computer, and carry on with what you can do here. If you have no such tools here, tell the user that computer use isn't available on their computer right now and that the Claude app on that computer may show why in the Computer use section of its Settings, then continue with what you can do here. Don't say a permission was denied unless a result says so.`, DAa = `If the request is about files or folders on the user's computer and you have device tools here (loaded or through tool search), such as mcp__${import_chunk_qdcbcsg7.$n}__device_list_dir, use them for that part; if it is and you have none, tell the user that files on their computer can't be reached right now.`, LAa = "Does nothing. This tool cannot connect a computer here. Tools whose names start with mcp__remote-devices__, if you have any, run on the user's computer; use whichever of them fits the task.", NAa = `This call did not connect a computer, and no tool here can. Tools whose names start with mcp__${import_chunk_qdcbcsg7.$n}__, if you have any, run on the user's computer; use whichever of them fits the task, loading it with ${import_chunk_t99xdws4.co} first, and waiting for that result, if it was only announced as available there and has not been loaded since. Otherwise carry on with the tools you have here, and if the task needs the user's computer, tell the user so.`, I4s = `This chat isn't linked to a computer right now, and no tool here can link one, including ${dzo} and the tools whose names start with enable__. That is a normal state, not an outage or a connection problem, so while you have no tools that run on the user's computer there is no point looking or waiting for them. The link can change during the conversation: if such tools (their names start with mcp__${import_chunk_qdcbcsg7.$n}__ or mcp__${import_chunk_prn6030k.Xi}__) are later in your tool list or announced to you, use them, whatever this result says. When your reply ends, the user may get a card under it about using one of their computers; you can't tell whether they get it. Tell the user it isn't linked in three or four plain sentences, in their language and without tool names, then do the task another way with the tools you have here if you can. For example: "I can't do that from here, because this chat isn't linked to a computer right now. If a card about using your computer appears below, you can go on from there. If none appears and you have the Claude desktop app on a computer, opening this chat there and sending a message can link it. If I still can't use your computer after that, adding a folder from that computer to this chat, in the desktop app, can." Say nothing about what you could do once it is linked or when that might be, and suggest no other steps or settings, with one exception: you can say that a file you made here can be put on their computer once it is linked. If the user's next message is only "Continue" or the name of a computer and you now have tools that run on their computer, go on with what they asked for, with those tools. If the user later says they did any of these and you still have no such tools, say that it still isn't linked, and name again only the steps they have not said they tried. If they say they tried all of them and you still have none, say only that it still isn't linked: no cause, and no step such as restarting or waiting.`, FAa = "Tools whose names contain claude-in-chrome, Claude_in_Chrome or claude-device__chrome_ need no linked computer: any in your list, or announced to you, are among the tools you have here.", M4s = `This chat isn't linked to a computer yet. The user gets a card under this reply that asks which of their computers to use. A press on it comes as their next message, and any message they type closes it. If you still write in this reply, call no other tool and say only, in one short sentence in their language, that they can pick a computer on the card below. If their next message is only "Continue" or the name of a computer and you now have tools whose names start with mcp__${import_chunk_qdcbcsg7.$n}__, go on with what they asked for, with those tools; if you see none, search for them once first, because they can take a moment to arrive, and only if there are still none say that you can't use it yet: no cause, and no step. If it turns the card down, for example "Not now", don't call this tool again for the same request: do the task another way with the tools you have here if you can, or tell them in one or two plain sentences, in their language and without tool names, that it needs their computer. If they type anything else, the card is gone, so don't point them to it: if they still want this done on their computer, call this tool again.`, v6r = `An earlier call in this conversation ended your reply so that a card could ask the user which of their computers to use. That card is gone, so don't point the user to it. This time your reply goes on. Answer the user in words: do the task another way with the tools you have here if you can, or say briefly, in their language and without tool names, that it needs their computer. When your reply ends, the user may get a new card under it; you can't tell whether they get it, so say at most that if a card appears below, they can go on from there. Suggest no other steps or settings. If tools whose names start with mcp__${import_chunk_qdcbcsg7.$n}__ are in your tool list or are announced to you, now or later, a computer is linked: use them, whatever this result says. Do not say that the user declined or ignored anything, and do not call this tool, or another whose name starts with enable__, again unless the user asks again for something that needs their computer.`, $Aa = `This chat isn't linked to a computer right now, so the browsers on the user's computer can't be used here, and no tool here can link one, including the tools whose names start with enable__. That is a normal state, not an outage. You have the cloud browser: its tools are the ones whose names start with mcp__${import_chunk_2mwshd9r.Cp}__ (load any that was only announced through ${import_chunk_t99xdws4.co} before you call it). Unless the user asked for a browser on their own computer, by any of its names or by describing it, do this step in the cloud browser and carry on without waiting for the user: don't bring up that the chat isn't linked, and don't suggest linking a computer or opening the desktop app. Your having called this tool is not such a request. If they did ask for their own browser, don't use the cloud browser yet: tell them in one or two plain sentences, in their language and without tool names, that you can't use that browser because this chat isn't linked to a computer right now, and that opening this chat in the Claude desktop app on a computer and sending a message can link it, then ask whether to use the cloud browser instead. A card about using one of their computers may appear under your reply: if their next message is only "Continue" or the name of a computer and you now have tools that run on their computer (their names start with mcp__${import_chunk_qdcbcsg7.$n}__ or mcp__${import_chunk_prn6030k.Xi}__), go on with what they asked for, with those tools and not the cloud browser.`, UAa = `Claude in Chrome is switched off for this chat, and no tool here can switch it on. Tell the user so in one or two plain sentences, in their language and without tool names. For example: "I can't use Chrome from here, because Claude in Chrome is switched off for this chat. You can switch it on in this chat's + menu, under Connectors or Plugins, on the web or in the Claude desktop app, if your organization allows Claude in Chrome." Then, if you have tools whose names contain Claude_Browser, offer to use the browser built into the Claude desktop app instead; otherwise do the task another way with the tools you have here if you can. Say nothing about what you could do once it is on, don't say that Chrome or its extension isn't connected, and suggest no other steps or settings for Claude in Chrome, with one exception: if the user says the switch already shows on, ask them to switch it off and on again there. If the user says they can't switch it on there, say only that you can't tell why from here, and that an organization can block Claude in Chrome for its members: no other cause, and no step. If the user says they switched it on, use Claude in Chrome's tools if you now have any (their names contain claude-in-chrome or Claude_in_Chrome); otherwise say only that you still can't use it here: no cause, and no step such as refreshing or waiting.`, BAa = `Claude in Chrome is switched off for this chat, and this chat isn't linked to a computer right now. No tool here can change either, including ${dzo} and the tools whose names start with enable__. Both are normal states, not an outage or a connection problem. While you have none of Claude in Chrome's tools (their names contain ${import_chunk_prn6030k.Xi}__ or Claude_in_Chrome__) there is no point looking or waiting for them. Either state can change during the conversation: if such tools are later in your tool list or announced to you, use them, whatever this result says. Tell the user both in three or four plain sentences, in their language and without tool names, then do the task another way with the tools you have here if you can. For example: "I can't use Chrome from here: Claude in Chrome is switched off for this chat, and the chat isn't linked to a computer right now. You can switch Claude in Chrome on in this chat's + menu, under Connectors or Plugins, on the web or in the Claude desktop app, if your organization allows Claude in Chrome. If you have the desktop app on a computer, opening this chat there and sending a message can link it. If I still can't use your computer after that, adding a folder from that computer to this chat, in the desktop app, can." Say nothing about what you could do after that or when that might be, and suggest no other steps or settings for either, with one exception: if the user says the switch already shows on, ask them to switch it off and on again there. If the user says they can't switch it on there, say only that you can't tell why from here, and that an organization can block Claude in Chrome for its members: no other cause, and no step. If the user says they did any of these and you still have none of Claude in Chrome's tools, say that you still can't use it here, with no cause, and name again only the steps they have not said they tried. If they say they tried all of them and you still have none, say only that you still can't use it here: no cause, and no step such as refreshing or waiting.`, WAa = `Claude in Chrome is off for the user's account, and no tool here can change that. You can't tell why. If the user didn't ask for Chrome or a browser on their own computer, and you can do this step with other tools you have here, do that and don't bring this up. Your having called this tool is not such a request. Otherwise tell the user in two or three plain sentences, in their language and without tool names. For example: "I can't use Chrome here, because Claude in Chrome is off for your account. If your Claude settings, on the web or in the desktop app, have a Claude in Chrome switch, check that it's on. If it's on, or there's no such switch, your plan or your organization may not allow Claude in Chrome." Then, if you have tools whose names contain Claude_Browser__, offer to use the browser built into the Claude desktop app instead; otherwise offer to do the task another way with the tools you have here, if you can. Suggest no other steps or settings for Claude in Chrome. If a card about using a computer shows under your reply and the user's next message is only "Continue" or the name of a computer, go on with what they asked for, with the tools you then have. If the user says they switched it on and you still have none of Claude in Chrome's tools (their names contain ${import_chunk_prn6030k.Xi}__ or Claude_in_Chrome__), say that the change can take a few minutes to reach this chat, and that they can ask you again then. If they ask again, call this tool once more; if it still says this, say only that you still can't use it here: no cause, and no step such as refreshing or waiting. If you later have such tools, use them.`, jAa = `The user's account or organization requires trusted devices, so Claude in Chrome can work in this chat only once it is linked to a computer, and a link may not be enough. The first time you tell the user that the chat isn't linked, add one sentence. For example: "Your account or organization requires trusted devices, so Claude in Chrome can't run in a chat that isn't linked to a computer."`, TQn = "This call enables nothing, and no tool here can add Claude in Chrome: this chat has none of its tools right now. Tell the user in one plain sentence, in their language and without tool names, that you can't use Claude in Chrome in this chat right now. Then, if you have tools whose names contain Claude_Browser, offer to use the browser built into the Claude desktop app instead; otherwise do the task another way with the tools you have here if you can. You don't know the cause: don't say that Chrome or its extension isn't connected, and suggest no steps or settings for Claude in Chrome. If you later have its tools (their names contain claude-in-chrome or Claude_in_Chrome), use them.";
